+import { afterEach, describe, expect, it, vi } from 'vitest';
+
+vi.mock('../src/collab/vela-workspace-context.js', async (importOriginal) => {
+  const actual = await importOriginal<typeof import('../src/collab/vela-workspace-context.js')>();
+  return {
